function schemaMatches(value,schema,path="value"){
  const fail=message=>{throw new Error(path+": "+message)};
  if(schema.oneOf){let matches=0;for(const branch of schema.oneOf){try{schemaMatches(value,branch,path);matches++}catch{}}if(matches!==1)fail("expected exactly one oneOf branch, got "+matches);return}
  if(schema.anyOf){let matches=false;for(const branch of schema.anyOf){try{schemaMatches(value,branch,path);matches=true;break}catch{}}if(!matches)fail("did not match any anyOf branch")}
  if(Object.hasOwn(schema,"const")&&value!==schema.const)fail("expected const "+JSON.stringify(schema.const));
  if(schema.enum&&!schema.enum.some(x=>x===value))fail("value is outside enum");
  const types=Array.isArray(schema.type)?schema.type:[schema.type];
  if(schema.type){const ok=types.some(t=>t==="null"?value===null:t==="object"?value!==null&&typeof value==="object"&&!Array.isArray(value):t==="array"?Array.isArray(value):t==="integer"?Number.isInteger(value):t==="number"?typeof value==="number"&&Number.isFinite(value):typeof value===t);if(!ok)fail("type does not match "+types.join("|"))}
  if(typeof value==="string"){if(schema.minLength!==undefined&&value.length<schema.minLength)fail("string too short");if(schema.maxLength!==undefined&&value.length>schema.maxLength)fail("string too long");if(schema.pattern&&!new RegExp(schema.pattern).test(value))fail("pattern mismatch")}
  if(typeof value==="number"){if(schema.minimum!==undefined&&value<schema.minimum)fail("below minimum");if(schema.maximum!==undefined&&value>schema.maximum)fail("above maximum");if(schema.exclusiveMinimum!==undefined&&value<=schema.exclusiveMinimum)fail("not above exclusive minimum")}
  if(Array.isArray(value)){if(schema.minItems!==undefined&&value.length<schema.minItems)fail("too few array items");if(schema.maxItems!==undefined&&value.length>schema.maxItems)fail("too many array items");if(schema.items)value.forEach((x,i)=>schemaMatches(x,schema.items,path+"["+i+"]"))}
  if(value!==null&&typeof value==="object"&&!Array.isArray(value)){for(const key of schema.required||[])if(!Object.hasOwn(value,key))fail("missing required field "+key);for(const [key,child] of Object.entries(schema.properties||{}))if(Object.hasOwn(value,key))schemaMatches(value[key],child,path+"."+key);if(schema.additionalProperties===false)for(const key of Object.keys(value))if(!Object.hasOwn(schema.properties||{},key))fail("undeclared field "+key)}
}
async function freePort(){
  const server = net.createServer();
  await new Promise((resolve,reject)=>server.once("error",reject).listen(0,"127.0.0.1",resolve));
  const port = server.address().port;
  await new Promise(resolve=>server.close(resolve));
  return port;
}
function cli(tool,input,expected=0){
  calledTools.add(tool);
  if(expected===0)schemaMatches(input,toolCatalog.get(tool).input_schema,tool+".input");
  const file = path.join(tempRoot,"input-"+Math.random().toString(16).slice(2)+".json");
  fs.writeFileSync(file,JSON.stringify(input),"utf8");
  const run = spawnSync(bin,[tool,"--input",file],{cwd:root,env:envBase,encoding:"utf8"});
  fs.rmSync(file,{force:true});
  assert.equal(run.status,expected,tool+" expected exit "+expected+"; stdout="+run.stdout+" stderr="+run.stderr);
  const out = JSON.parse(run.stdout.trim());
  assert.equal(out.tool,tool);
  schemaMatches(out,toolCatalog.get(tool).output_schema,tool);
  return out;
}
async function waitForHealth(base){
  for(let i=0;i<80;i++){
    if(serverProcess.exitCode!==null)throw new Error("isolated server exited early: "+serverOutput);
    try{const r=await fetch(base+"/api/health");if(r.ok)return await r.json()}catch{}
    await new Promise(resolve=>setTimeout(resolve,100));
  }
  throw new Error("isolated server failed to start: "+serverOutput);
}
async function post(base,path,body,expected=200){
  const r=await fetch(base+path,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(body)});
  const payload=await r.json();assert.equal(r.status,expected,JSON.stringify(payload));return payload;
}
